	// Calculate if there are any relevant incoming changes

	// There are unsaved changes . This can be detected by calling tw.system.coachUtils.hasLocallyChangedInputVars(). Here, however, this variable is
	// set by the Data Section coach view when it detects that a child view's data binding has changed.
	if(tw.local.unsavedLocalChanges === true || tw.system.coachUtils.hasLocallyChangedInputVars()){
		
		if(!tw.local.unsavedLocalChanges)
			tw.local.unsavedLocalChanges = true;
			
		// Call the helper function to update the incoming and local changes.
		checkIncomingChanges(tw.local, tw.system.coachUtils.getLocallyChangedVars(), tw.system.dataChangeUtils.getIncomingVars())		 
		
	} else if(tw.system.coachUtils.getLocallyChangedVars().length > 0) { // No pending changes to be merged, or local changes
	
		// Apply incoming changes to the local variables.
		tw.system.dataChangeUtils.applyAllIncomingVars();
		tw.local.incomingChangesMerged = true; // Signal that changes were applied automatically. The Data Section can listen and pop up a notification.
	 
	}

}); "]}},{"targetRef":"2025.d84cd4a4-944e-4d70-8ff3-2552da2baff3","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Collect change information","declaredType":"sequenceFlow","id":"2027.951970a7-2fc5-491e-96ed-8e486ea6a4f1","sourceRef":"2025.19317841-7f8a-442f-8310-a30273b38e2f"},{"targetRef":"2025.42daf596-8721-4769-b9be-458308d0fe94","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Stay on page","declaredType":"sequenceFlow","id":"2027.9540bce1-f1fc-4df7-9608-7e2d8fa7c7c1","sourceRef":"2025.d84cd4a4-944e-4d70-8ff3-2552da2baff3"}],"startQuantity":1,"extensionElements":{"nodeVisualInfo":[{"width":95,"x":51,"y":463,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Data Change","triggeredByEvent":true,"isForCompensation":false,"completionQuantity":1,"declaredType":"subProcess","id":"2025.e945f243-307a-4e05-a134-490c44b9378d"},{"targetRef":"2025.8f401771-780b-4747-83fc-ecde90e88b02","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"topCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":true}]},"name":"Yes","declaredType":"sequenceFlow","id":"2027.8511e58f-e95b-4521-a22b-1558861b78ef","sourceRef":"2025.1c0b36ad-a52a-44cb-964a-25c4507f2a73"},{"startQuantity":1,"outgoing":["2027.3aa013c9-c903-4c9c-af12-1ff6e088d0a0"],"incoming":["2027.87fb1a1a-f3fc-4c8a-935d-56bd81936ba0"],"default":"2027.3aa013c9-c903-4c9c-af12-1ff6e088d0a0","extensionElements":{"nodeVisualInfo":[{"width":95,"x":523,"y":103,"declaredType":"TNodeVisualInfo","height":70}]},"name