	// Initialize variables that support data change syncrhonization. 
	
	// This can only be done once the URL for the helper functions is returned by the 
	// Server Sice Init Data. Since this is can also be invoked as part of auto refresh the initialization
	// should only happen if the variables are undefined.
	
	if(tw.local.originalInput == undefined && tw.local.localChanges == undefined && tw.local.incomingChanges == undefined){
		initializeDataSyncronizationVariables(tw.local); // Intialize variables
	}
	
}); 
